package com.kareem.lifeos;

import android.app.Activity;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import com.kareem.lifeos.actions.PersistentActionQueue;
import com.kareem.lifeos.actions.TeyaApprovalReceiver;
import java.text.DateFormat;
import java.util.Date;
import java.util.List;

/** Approval surface. External/write actions never execute merely because they were proposed. */
public final class ActionCenterActivity extends Activity {
    private static final int BG=Color.rgb(13,17,23),SURFACE=Color.rgb(22,27,34),BORDER=Color.rgb(48,54,61),TEXT=Color.rgb(230,237,243),MUTED=Color.rgb(139,148,158),GREEN=Color.rgb(63,185,80),BLUE=Color.rgb(47,129,247),RED=Color.rgb(248,81,73),YELLOW=Color.rgb(210,153,34);
    private PersistentActionQueue queue; private LinearLayout content; private Button pending,history;
    @Override public void onCreate(Bundle s){super.onCreate(s);queue=new PersistentActionQueue(this);render();showPending();}
    @Override protected void onResume(){super.onResume();if(content!=null)showPending();}

    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(14),dp(10),dp(14),dp(8));head.setBackgroundColor(SURFACE);Button back=secondary("‹");back.setContentDescription("Back");back.setOnClickListener(v->finish());head.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=text("Action Center",21,TEXT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(dp(10),0,0,0);head.addView(title,tp);root.addView(head);root.addView(divider());LinearLayout tabs=new LinearLayout(this);tabs.setPadding(dp(8),0,dp(8),0);pending=tab("Pending");history=tab("History");tabs.addView(pending,new LinearLayout.LayoutParams(0,dp(48),1));tabs.addView(history,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(tabs);root.addView(divider());ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),dp(14),dp(16),dp(24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));pending.setOnClickListener(v->showPending());history.setOnClickListener(v->showHistory());setContentView(root);}

    private void showPending(){select(pending);content.removeAllViews();section("Approval required","Calls, messages, reminders, calendar changes, and other external actions always wait for your approval here.");List<PersistentActionQueue.Item> xs=queue.pending();if(xs.isEmpty()){empty("No actions are waiting for approval.");return;}for(PersistentActionQueue.Item x:xs)card(x,true);}
    private void showHistory(){select(history);content.removeAllViews();section("Action history","A traceable record of what was proposed, what you approved, and what happened.");List<PersistentActionQueue.Item> xs=queue.history();if(xs.isEmpty()){empty("No action history yet.");return;}for(PersistentActionQueue.Item x:xs)card(x,false);}
    private void card(PersistentActionQueue.Item x,boolean controls){LinearLayout r=row();String risk=risk(x.proposal.risk.name());r.addView(badge(risk,x.proposal.risk.name().contains("IRREVERSIBLE")||x.proposal.risk.name().contains("SENSITIVE")?RED:YELLOW));TextView t=text(human(x.proposal.actionType)+(x.proposal.target.isEmpty()?"":" · "+x.proposal.target),15,TEXT);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(7),0,dp(4));r.addView(t);if(!x.proposal.payloadSummary.isEmpty())r.addView(text(x.proposal.payloadSummary,13,TEXT));r.addView(meta("Status: "+human(x.state)+(x.proposal.situationId.isEmpty()?"":" · Linked to a situation")));if(x.approval!=null)r.addView(meta((x.approval.approved?"Approved":"Denied")+" · "+DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new Date(x.approval.approvedAt))));if(!x.result.isEmpty()){TextView result=text(x.result,12,"failed".equals(x.state)?RED:GREEN);result.setPadding(0,dp(8),0,0);r.addView(result);}if(controls){LinearLayout a=new LinearLayout(this);a.setPadding(0,dp(10),0,0);Button deny=secondary("Deny");deny.setTextColor(RED);deny.setOnClickListener(v->{queue.decide(x.proposal.proposalId,false);showPending();});Button approve=primary("Approve & execute");approve.setOnClickListener(v->{queue.decide(x.proposal.proposalId,true);TeyaApprovalReceiver.executeApproved(this,x);showHistory();});a.addView(deny,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(8),0,0,0);a.addView(approve,p);r.addView(a);}content.addView(r);}

    private void section(String t,String s){TextView h=text(t,20,TEXT);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(h);TextView m=text(s,12,MUTED);m.setPadding(0,dp(3),0,dp(12));content.addView(m);}private void empty(String s){LinearLayout r=row();r.addView(text(s,14,MUTED));content.addView(r);}private LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(14),dp(13),dp(14),dp(13));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(8));r.setLayoutParams(p);r.setBackground(round(SURFACE,BORDER,8));return r;}private TextView badge(String s,int c){TextView v=text(s,11,c);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setPadding(dp(8),dp(4),dp(8),dp(4));v.setLayoutParams(new LinearLayout.LayoutParams(-2,-2));v.setBackground(round(Color.TRANSPARENT,c,20));return v;}private TextView meta(String s){TextView v=text(s,11,MUTED);v.setPadding(0,dp(8),0,0);return v;}private Button tab(String s){Button b=new Button(this);b.setText(s);b.setTextColor(MUTED);b.setTextSize(12);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);return b;}private void select(Button b){for(Button x:new Button[]{pending,history}){x.setTextColor(x==b?TEXT:MUTED);x.setTypeface(Typeface.DEFAULT,x==b?Typeface.BOLD:Typeface.NORMAL);}}private Button secondary(String s){Button b=new Button(this);b.setText(s);b.setTextColor(TEXT);b.setTextSize(12);b.setAllCaps(false);b.setGravity(Gravity.CENTER);b.setBackground(round(SURFACE,BORDER,7));return b;}private Button primary(String s){Button b=secondary(s);b.setBackground(round(BLUE,BLUE,7));b.setTextColor(Color.WHITE);return b;}private View divider(){View v=new View(this);v.setBackgroundColor(BORDER);v.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(1)));return v;}private GradientDrawable round(int f,int s,int r){GradientDrawable g=new GradientDrawable();g.setColor(f);g.setCornerRadius(dp(r));g.setStroke(dp(1),s);return g;}private TextView text(String s,int n,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(n);v.setTextColor(c);v.setLineSpacing(0,1.08f);return v;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private static String human(String value){String x=value==null?"":value.replace('_',' ').trim().toLowerCase();return x.isEmpty()?"Action":Character.toUpperCase(x.charAt(0))+x.substring(1);}private static String risk(String value){if("READ_ONLY".equals(value))return "Review only";if("REVERSIBLE_WRITE".equals(value))return "Can be undone";if("IRREVERSIBLE_WRITE".equals(value))return "Cannot be undone";return "Sensitive action";}
}
